namespace DopingRetain.Api.Data;

/// <summary>
/// Sixth-grade demo content shared by all sixth-grade students. Topic Ids, subjects and units come from the
/// curriculum catalog (topic_id, lesson_name, unit_id, unit_name); the catalog has no questions or answers, so
/// the questions and reminders below are authored demo content. Each reminder carries its own mini quiz
/// question, so reminder i and mini quiz question i always belong together.
/// </summary>
public static class SixthGradeContent
{
    /// <param name="Id">Catalog topic_id.</param>
    /// <param name="Title">Catalog topic_name; repeated across units, so the unit is always shown with it.</param>
    public sealed record ContentTopic(
        string Id, string Title, string Subject, int UnitId, string UnitName, Reminder[] Reminders, NormalQuestion[] NormalTest);

    /// <summary>A Hap Bilgi reminder and the mini quiz question that checks it.</summary>
    public sealed record Reminder(SummaryPoint Point, MiniQuizQuestion Question);

    public sealed record MiniQuizQuestion(string Text, string[] Options, int CorrectIndex, string Explanation);

    public sealed record NormalQuestion(string Text, string[] Options, int CorrectIndex);

    public static string MiniQuizQuestionId(string topicId, int number) => $"{topicId}-mq{number}";

    public static string NormalQuestionId(string topicId, int number) => $"{topicId}-nt{number:00}";

